using System;
using System.Collections.Generic;
using System.Linq;

namespace CampaignCore;

// Effects are selected by stable keys. A team classifier is enabled only inside
// the native consumer listed here, never as the team's global identity.
public sealed class OpponentEffect
{
    public string Key { get; }
    public string Label { get; }
    public string Group { get; }
    public string Help { get; }
    public string Classifier { get; }
    public string[] Consumers { get; }
    public string Exclusive { get; }
    public OpponentEffect(string key, string label, string group, string help, string classifier = "", string consumers = "", string exclusive = "")
    {
        Key = key; Label = label; Group = group; Help = help;
        Classifier = classifier; Consumers = consumers.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
        Exclusive = exclusive;
    }
}

