    public static HashSet<string> Parse(string value) => new HashSet<string>((value ?? "").Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)
        .Select(x => x.Trim()).Where(x => x.Length > 0 && !x.Equals("None", StringComparison.OrdinalIgnoreCase)), StringComparer.OrdinalIgnoreCase);
    public static string Serialize(IEnumerable<string> values) { var items = values.Distinct(StringComparer.OrdinalIgnoreCase).ToArray(); return items.Length == 0 ? "None" : string.Join(", ", items); }
    public static IEnumerable<string> Conflicts(IEnumerable<string> values)
    {
        var selected = new HashSet<string>(values, StringComparer.OrdinalIgnoreCase);
        foreach (var group in All.Where(e => selected.Contains(e.Key) && e.Exclusive.Length > 0).GroupBy(e => e.Exclusive))
            if (group.Count() > 1) yield return "Choose one: " + string.Join(" / ", group.Select(e => e.Label));
    }
    private static readonly Dictionary<string, List<string>> Routes = BuildRoutes();
    private static Dictionary<string, List<string>> BuildRoutes()
    {
        var routes = new Dictionary<string, List<string>>();
        foreach (var effect in All)
            foreach (string consumer in effect.Consumers)
            {
                string route = consumer + "/" + effect.Classifier;
                if (!routes.TryGetValue(route, out var keys)) routes[route] = keys = new List<string>();
                keys.Add(effect.Key);
            }
        return routes;
    }
    public static bool Allows(ISet<string> selected, string consumer, string classifier) =>
        Routes.TryGetValue(consumer + "/" + classifier, out var keys) && keys.Any(selected.Contains);
    public static HashSet<string> FromPreset(string preset)
    {
        preset = OpponentOptions.Normalize(preset, OpponentOptions.Presets.Keys, "Standard");
        string classifier = OpponentOptions.Presets[preset];
        var result = new HashSet<string>(All.Where(e => e.Classifier == classifier).Select(e => e.Key), StringComparer.OrdinalIgnoreCase);
        if (preset == "Mountaineers") result.Add("hide-jersey-number");
        if (preset == "Crusaders") result.Add("hide-kit-markings");
        return result;
    }
    public static readonly string[] Offense = { "Standard", "Default", "Blitz", "Low", "Overload", "Spread", "Umbrella" };
    public static string ResolveOffense(string value) => OpponentOptions.Normalize(value, Offense, "Standard");
    public static readonly string[] Defense = { "Standard", "ManToMan", "Box" };
    public static string ResolveDefense(string value) => OpponentOptions.Normalize(value, Defense, "Standard");
}
